def getSkyline(buildings: list[list[int]]) -> list[list[int]]:
    import heapq
    events = []
    for L, R, H in buildings:
        events.append((L, -H, R))
        events.append((R, 0, 0))
    events.sort()
    res = [[0, 0]]
    live = [(0, float('inf'))]
    for pos, negH, R in events:
        while live[0][1] <= pos:
            heapq.heappop(live)
        if negH != 0:
            heapq.heappush(live, (negH, R))
        curr_h = -live[0][0]
        if res[-1][1] != curr_h:
            res.append([pos, curr_h])
    return res[1:]

